import{_ as r,o as n,c as i,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/reportdesigner/serien-e-mail.png",t="/bilder/reportdesigner/serien-e-mail-betreff.png",d="/bilder/reportdesigner/serien-e-mail-gruppen.png",f=JSON.parse('{"title":"Reportausgaben als Serien-E-Mail versenden","description":"","frontmatter":{"title":"Reportausgaben als Serien-E-Mail versenden","source_pageid":1577,"source_revision":6822},"headers":[],"relativePath":"reporting/reportdesigner/serien-e-mail-versand.md","filePath":"reporting/reportdesigner/serien-e-mail-versand.md"}'),l={name:"reporting/reportdesigner/serien-e-mail-versand.md"};function u(p,e,o,h,g,c){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="reportausgaben-als-serien-e-mail-versenden" tabindex="-1">Reportausgaben als Serien-E-Mail versenden <a class="header-anchor" href="#reportausgaben-als-serien-e-mail-versenden" aria-label="Permalink to &quot;Reportausgaben als Serien-E-Mail versenden&quot;">​</a></h1><p>Ein passend eingerichteter Report kann pro Gruppenwechsel eine PDF-Datei erzeugen und an die zugehörige Zielperson versenden. Prüfen Sie dafür die Gruppeneinstellungen und die für die jeweilige Zielgruppe beschriebenen Voraussetzungen.</p><h2 id="voraussetzungen" tabindex="-1">Voraussetzungen <a class="header-anchor" href="#voraussetzungen" aria-label="Permalink to &quot;Voraussetzungen&quot;">​</a></h2><p>Der Report muss eine <strong>Gruppe</strong> enthalten. Eine Gruppe fasst zum Beispiel die Daten einer Person oder einer Klasse zusammen. Ändert sich der Wert des Gruppierungsfeldes, etwa <code>Schueler.ID</code>, beginnt die nächste Gruppe. Dies heißt <strong>Gruppenwechsel</strong>. Für jede Gruppe wird eine eigene PDF-Datei erzeugt und automatisch an den zugehörigen Empfänger gesendet.</p><p>In dieser Gruppe muss das Auswahlfeld &quot;Neue Seite beginnen&quot;, &quot;Neue Datei erzeugen&quot; und &quot;Neue Datei als E-Mail versenden&quot; aktiviert sein. Nur mit diesen Einstellungen erzeugt der Reportdesigner nach jedem Gruppenwechsel ein neues PDF-Dokument und hängt dieses einer E-Mail an die Zielgruppe an.</p><p><a href="/bilder/reportdesigner/serien-e-mail.png"><img src="'+s+'" alt="Serien-E-Mail-Versand" loading="lazy"></a></p><p><em>Serien-E-Mail-Versand</em></p><p>In Abhängigkeit des Designs eines Reports können diese als Serien-E-Mail versendet werden. Hierbei wird der Report nicht gedruckt, sondern als PDF-Anhang an die jeweilige Zielperson per E-Mail versendet.</p><p><a href="/bilder/reportdesigner/serien-e-mail-betreff.png"><img src="'+t+'" alt="Betreff und Nachrichtentext erstellen" loading="lazy"></a></p><p><em>Betreff und Nachrichtentext erstellen</em></p><p>Wenn Sie die Option &quot;als Serien-E-Mail versenden&quot; aktivieren, öffnet sich nach kurzer Zeit ein E-Mail-Fenster, in welchem Sie Betreff und E-Mail-Text anpassen können. Nach der Bestätigung dieses Standards werden alle folgenden E-Mails mit dem soeben definierten Betreff und dem E-Mail-Text an die jeweiligen Zielpersonen versendet.</p><p><a href="/bilder/reportdesigner/serien-e-mail-gruppen.png"><img src="'+d+'" alt="Gruppe als Voraussetzung" loading="lazy"></a></p><p><em>Gruppe als Voraussetzung</em></p><h2 id="gruppierung-und-empfanger-zuordnen" tabindex="-1">Gruppierung und Empfänger zuordnen <a class="header-anchor" href="#gruppierung-und-empfanger-zuordnen" aria-label="Permalink to &quot;Gruppierung und Empfänger zuordnen&quot;">​</a></h2><h3 id="gruppe-schueler-id" tabindex="-1">Gruppe Schueler.ID <a class="header-anchor" href="#gruppe-schueler-id" aria-label="Permalink to &quot;Gruppe Schueler.ID&quot;">​</a></h3><p>Bei der Gruppierung nach <code>Schueler.ID</code> erhält jede Schülerin oder jeder Schüler eine eigene E-Mail. In den Programmeinstellungen legen Sie fest, ob die private oder die schulische Adresse verwendet wird. Jede Seite beziehungsweise Gruppe darf nur Daten der empfangenden Person enthalten. Passende Vorlagen der Basisreportsammlung tragen den Zusatz <strong>@SuS</strong>.</p><h3 id="gruppe-erzieher-id" tabindex="-1">Gruppe Erzieher.ID <a class="header-anchor" href="#gruppe-erzieher-id" aria-label="Permalink to &quot;Gruppe Erzieher.ID&quot;">​</a></h3><p>Bei der Gruppierung nach <code>Erzieher.ID</code> geht die E-Mail an die jeweiligen Erziehungsberechtigten. Dafür müssen eine gültige E-Mail-Adresse und <strong>Erhält Anschreiben</strong> hinterlegt sein. Jede Seite beziehungsweise Gruppe darf nur Daten des zugehörigen Kindes enthalten. Passende Vorlagen der Basisreportsammlung tragen den Zusatz <strong>@Erzieher</strong>.</p><h3 id="gruppe-schueler-klasse" tabindex="-1">Gruppe Schueler.Klasse <a class="header-anchor" href="#gruppe-schueler-klasse" aria-label="Permalink to &quot;Gruppe Schueler.Klasse&quot;">​</a></h3><p>Bei der Gruppierung nach <code>Schueler.Klasse</code> erhält die jeweilige Klassenleitung die E-Mail. Die Programmeinstellungen bestimmen, ob die private oder die schulische Adresse verwendet wird. Jede Seite beziehungsweise Gruppe darf nur Daten der zugehörigen Klasse enthalten. Passende Vorlagen der Basisreportsammlung tragen den Zusatz <strong>@KL</strong>.</p><h3 id="gruppe-kurse-id" tabindex="-1">Gruppe Kurse.ID <a class="header-anchor" href="#gruppe-kurse-id" aria-label="Permalink to &quot;Gruppe Kurse.ID&quot;">​</a></h3><p>Reports mit Gruppenwechsel Kurse.ID werden per E-Mail an die jeweilige Kursleitung versendet. In den Einstellungen von SchILD-NRW 3 kann festgelegt werden, ob die E-Mail an die private oder die schulische E-Mail-Adresse der Kursleitung versendet wird. Ein so versendeter Report darf pro Seite bzw. Gruppe nur Informationen zu Schülern des Kurses enthalten.</p><h3 id="gruppe-lehrer-id" tabindex="-1">Gruppe Lehrer.ID <a class="header-anchor" href="#gruppe-lehrer-id" aria-label="Permalink to &quot;Gruppe Lehrer.ID&quot;">​</a></h3><p>Bei der Gruppierung nach <code>Lehrer.ID</code> erhält jede Lehrkraft eine eigene E-Mail. In den Programmeinstellungen legen Sie fest, ob die private oder die schulische Adresse verwendet wird. Jede Seite beziehungsweise Gruppe darf nur Daten der empfangenden Lehrkraft enthalten. Passende Vorlagen der Basisreportsammlung tragen den Zusatz <strong>@LuL</strong>.</p><h3 id="gruppe-schueler-schulwechselnr" tabindex="-1">Gruppe Schueler.SchulwechselNr <a class="header-anchor" href="#gruppe-schueler-schulwechselnr" aria-label="Permalink to &quot;Gruppe Schueler.SchulwechselNr&quot;">​</a></h3><p>Reports mit Gruppenwechsel LSchueler.SchulwechselNr werden per E-Mail an die jeweilige aufnehmende Schule versendet. Ein so versendeter Report darf pro Seite bzw. Gruppe nur Informationen zu Schülern enthalten, welche von der aufnehmenden Schule aufgenommen werden. In der Basisreportsammlung sind solche Reports mit dem Zusatz @aufnehmende Schule gekennzeichnet.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Serien-E-Mail-Versand" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6822.</p>',28)])])}const b=r(l,[["render",u]]);export{f as __pageData,b as default};
